CREATE TABLE t1(x, y); CREATE TRIGGER Trigger1 DELETE ON t1 BEGIN SELECT t1.*, t1.x FROM t1 ORDER BY t1.x; END; ALTER TABLE t1 RENAME x TO z; ALTER TABLE t1 RENAME TO t2; CREATE TRIGGER tr2 AFTER DELETE ON t2 BEGIN SELECT z, y FROM (SELECT t2.* FROM t2); END; DELETE FROM t2; ALTER TABLE t2 RENAME TO t3;